import React from 'react';
import { Pressable, StyleSheet, View, type StyleProp, type ViewStyle } from 'react-native';

import { FileViewIcon } from './FileViewIcon';
import { fileViewChoices, nextFileView, type FileViewMode } from './fileViewLogic';

/**
 * The buttons that choose how the files are shown: list, expanded list, grid.
 *
 * Two shapes. By default the icons sit side by side and the chosen one is lit. With `compact`
 * there is one button showing the view in use, and each press moves to the next view; use it
 * where a toolbar has no room for three.
 */

export type ViewSwitcherProps = {
  value: FileViewMode;
  onChange: (mode: FileViewMode) => void;
  /** The views this app offers. All of them when left out. */
  modes?: readonly FileViewMode[];
  compact?: boolean;
  /** The side of one button. */
  size?: number;
  /** The colour of an icon that is not chosen. */
  color?: string;
  /** The colour behind the chosen icon. */
  accent?: string;
  /** The colour of the chosen icon, on the accent. */
  onAccent?: string;
  /** The colour of the strip the buttons sit on. */
  track?: string;
  style?: StyleProp<ViewStyle>;
};

export function ViewSwitcher({
  value,
  onChange,
  modes,
  compact = false,
  size = 32,
  color = 'rgba(255,255,255,0.72)',
  accent = '#fff',
  onAccent = '#111',
  track = 'rgba(255,255,255,0.10)',
  style,
}: ViewSwitcherProps) {
  const choices = fileViewChoices(modes);
  const icon = Math.round(size * 0.56);
  const corner = Math.round(size * 0.28);

  if (compact) {
    const current = choices.find((choice) => choice.value === value) ?? choices[0];
    if (!current) return null;
    return (
      <Pressable
        style={[styles.one, { width: size + 6, height: size + 6, borderRadius: corner + 3, backgroundColor: track }, style]}
        onPress={() => onChange(nextFileView(value, modes))}
        accessibilityRole="button"
        accessibilityLabel={`${current.label}. Change view`}
        hitSlop={6}
      >
        <FileViewIcon name={current.icon} size={icon} color={color} />
      </Pressable>
    );
  }

  return (
    <View style={[styles.strip, { borderRadius: corner + 3, backgroundColor: track }, style]} accessibilityRole="tablist">
      {choices.map((choice) => {
        const chosen = choice.value === value;
        return (
          <Pressable
            key={choice.value}
            style={[
              styles.button,
              { width: size, height: size, borderRadius: corner },
              chosen && { backgroundColor: accent },
            ]}
            onPress={() => onChange(choice.value)}
            accessibilityRole="tab"
            accessibilityLabel={choice.label}
            accessibilityState={{ selected: chosen }}
            hitSlop={{ top: 6, bottom: 6 }}
          >
            <FileViewIcon name={choice.icon} size={icon} color={chosen ? onAccent : color} />
          </Pressable>
        );
      })}
    </View>
  );
}

const styles = StyleSheet.create({
  strip: { flexDirection: 'row', padding: 3, gap: 2, alignSelf: 'flex-start' },
  button: { alignItems: 'center', justifyContent: 'center' },
  one: { alignItems: 'center', justifyContent: 'center' },
});
